// t16_vecadd -- generated by gen_t16_vecadd.py; do not edit by hand.
//
// The instruction sequence a Triton vector_add must lower to, written by
// hand first so the compiler has something to be compared against.
// n = 40, BLOCK = 16: 3 programs, the last one masked.
//
// Role 0 runs every program id in a loop, because this bench launches one
// context rather than a grid. The body is what matters.
.org 0
start:
    .li       s1, #40                  // n
    .li       s2, #16384             // x
    .li       s3, #17408             // y
    .li       s4, #18432             // out
    .li       s5, #0                     // pid

loop:
    // offs = pid * BLOCK + arange(0, BLOCK)
    .li       s6, #16
    s.mul     s7, s5, s6                 // pid * BLOCK
    v.iota    v1                         // arange(0, BLOCK)
    v.splat   v2, s7
    v.add     v3, v1, v2                 // offs

    // mask = offs < n
    v.splat   v4, s1
    v.cmp.lt  p1, v3, v4

    // The offsets are contiguous, so a plain vector load reaches them:
    // ISA sec 9.1 gives lane i the address base + i*sz. No gather is
    // needed, and emitting one would cost per-lane addressing for nothing.
    s.shli    s8, s7, #2                 // byte offset = pid*BLOCK*4
    s.add     s9, s2, s8                 // &x[pid*BLOCK]
    s.add     s10, s3, s8                // &y[pid*BLOCK]
    s.add     s11, s4, s8                // &out[pid*BLOCK]

    // other=0.0 is a value, not an absence (sec 12). The masked-off lanes
    // keep what the register already held, so it has to be set first.
    v.movi    v5, #0
    v.movi    v6, #0
    @p1 v.ld.w v5, [s9, #0]
    @p1 v.ld.w v6, [s10, #0]

    vf.add    v7, v5, v6
    @p1 v.st.w [s11, #0], v7

    s.addi    s5, s5, #1
    .li       s12, #3
    s.cmp.lt  s13, s5, s12
    br.nz     s13, loop

    // ---- check every element, including the masked tail ----
    .li       s20, #18432
    s.ld.w    s21, [s20, #0]
    .assert_eq s21, #0x3f800000, #1
    s.ld.w    s21, [s20, #4]
    .assert_eq s21, #0x3fe00000, #2
    s.ld.w    s21, [s20, #8]
    .assert_eq s21, #0x40200000, #3
    s.ld.w    s21, [s20, #12]
    .assert_eq s21, #0x40500000, #4
    s.ld.w    s21, [s20, #16]
    .assert_eq s21, #0x40800000, #5
    s.ld.w    s21, [s20, #20]
    .assert_eq s21, #0x40980000, #6
    s.ld.w    s21, [s20, #24]
    .assert_eq s21, #0x40b00000, #7
    s.ld.w    s21, [s20, #28]
    .assert_eq s21, #0x40c80000, #8
    s.ld.w    s21, [s20, #32]
    .assert_eq s21, #0x40e00000, #9
    s.ld.w    s21, [s20, #36]
    .assert_eq s21, #0x40f80000, #10
    s.ld.w    s21, [s20, #40]
    .assert_eq s21, #0x41080000, #11
    s.ld.w    s21, [s20, #44]
    .assert_eq s21, #0x41140000, #12
    s.ld.w    s21, [s20, #48]
    .assert_eq s21, #0x41200000, #13
    s.ld.w    s21, [s20, #52]
    .assert_eq s21, #0x412c0000, #14
    s.ld.w    s21, [s20, #56]
    .assert_eq s21, #0x41380000, #15
    s.ld.w    s21, [s20, #60]
    .assert_eq s21, #0x41440000, #16
    s.ld.w    s21, [s20, #64]
    .assert_eq s21, #0x41500000, #17
    s.ld.w    s21, [s20, #68]
    .assert_eq s21, #0x415c0000, #18
    s.ld.w    s21, [s20, #72]
    .assert_eq s21, #0x41680000, #19
    s.ld.w    s21, [s20, #76]
    .assert_eq s21, #0x41740000, #20
    s.ld.w    s21, [s20, #80]
    .assert_eq s21, #0x41800000, #21
    s.ld.w    s21, [s20, #84]
    .assert_eq s21, #0x41860000, #22
    s.ld.w    s21, [s20, #88]
    .assert_eq s21, #0x418c0000, #23
    s.ld.w    s21, [s20, #92]
    .assert_eq s21, #0x41920000, #24
    s.ld.w    s21, [s20, #96]
    .assert_eq s21, #0x41980000, #25
    s.ld.w    s21, [s20, #100]
    .assert_eq s21, #0x419e0000, #26
    s.ld.w    s21, [s20, #104]
    .assert_eq s21, #0x41a40000, #27
    s.ld.w    s21, [s20, #108]
    .assert_eq s21, #0x41aa0000, #28
    s.ld.w    s21, [s20, #112]
    .assert_eq s21, #0x41b00000, #29
    s.ld.w    s21, [s20, #116]
    .assert_eq s21, #0x41b60000, #30
    s.ld.w    s21, [s20, #120]
    .assert_eq s21, #0x41bc0000, #31
    s.ld.w    s21, [s20, #124]
    .assert_eq s21, #0x41c20000, #32
    s.ld.w    s21, [s20, #128]
    .assert_eq s21, #0x41c80000, #33
    s.ld.w    s21, [s20, #132]
    .assert_eq s21, #0x41ce0000, #34
    s.ld.w    s21, [s20, #136]
    .assert_eq s21, #0x41d40000, #35
    s.ld.w    s21, [s20, #140]
    .assert_eq s21, #0x41da0000, #36
    s.ld.w    s21, [s20, #144]
    .assert_eq s21, #0x41e00000, #37
    s.ld.w    s21, [s20, #148]
    .assert_eq s21, #0x41e60000, #38
    s.ld.w    s21, [s20, #152]
    .assert_eq s21, #0x41ec0000, #39
    s.ld.w    s21, [s20, #156]
    .assert_eq s21, #0x41f20000, #40

    // Lanes past n were masked off. A predicated store must not write
    // them, so the sentinel below has to survive untouched -- this is the
    // half of masking that a passing arithmetic check would not catch.
    s.ld.w    s21, [s20, #160]
    .assert_eq s21, #0xdeadbeef, #41
    s.ld.w    s21, [s20, #164]
    .assert_eq s21, #0xdeadbeef, #42
    s.ld.w    s21, [s20, #168]
    .assert_eq s21, #0xdeadbeef, #43
    s.ld.w    s21, [s20, #172]
    .assert_eq s21, #0xdeadbeef, #44
    s.ld.w    s21, [s20, #176]
    .assert_eq s21, #0xdeadbeef, #45
    s.ld.w    s21, [s20, #180]
    .assert_eq s21, #0xdeadbeef, #46
    s.ld.w    s21, [s20, #184]
    .assert_eq s21, #0xdeadbeef, #47
    s.ld.w    s21, [s20, #188]
    .assert_eq s21, #0xdeadbeef, #48

    exit

.org 0x4000
